-- Logistics Master Database schema (generated by the ETL from etl/lpl/schema.py - do not edit by hand)
-- ETL version 1.0.0
-- Types are portable: TEXT, INTEGER, DOUBLE PRECISION, DATE, TIMESTAMP. For PostgreSQL, run as-is
-- (CREATE ... IF NOT EXISTS is supported); load data from output/csv with COPY ... CSV HEADER.

CREATE TABLE IF NOT EXISTS REFERENCE_BATCH (
    batch_id TEXT NOT NULL,
    batch_no INTEGER NOT NULL UNIQUE,
    batch_name TEXT NOT NULL,
    description TEXT,
    PRIMARY KEY (batch_id)
);

CREATE TABLE IF NOT EXISTS REFERENCE_CATEGORY (
    category_id TEXT NOT NULL,
    category_name TEXT NOT NULL,
    mdr_prefix_observed TEXT,
    description TEXT,
    PRIMARY KEY (category_id)
);

CREATE TABLE IF NOT EXISTS REFERENCE_MAPPING_STATUS (
    status_code TEXT NOT NULL,
    is_linked INTEGER NOT NULL,
    sort_order INTEGER NOT NULL,
    description TEXT NOT NULL,
    PRIMARY KEY (status_code)
);

CREATE TABLE IF NOT EXISTS REFERENCE_MDR_STATUS (
    mdr_status_code TEXT NOT NULL,
    label TEXT NOT NULL,
    description TEXT,
    PRIMARY KEY (mdr_status_code)
);

CREATE TABLE IF NOT EXISTS REFERENCE_READINESS_STATUS (
    status_code TEXT NOT NULL,
    label TEXT NOT NULL,
    short_label TEXT NOT NULL,
    color TEXT NOT NULL,
    sort_order INTEGER NOT NULL,
    rule TEXT NOT NULL,
    action TEXT NOT NULL,
    PRIMARY KEY (status_code)
);

CREATE TABLE IF NOT EXISTS IMPORT_HISTORY (
    import_id TEXT NOT NULL,
    started_at TIMESTAMP NOT NULL,
    finished_at TIMESTAMP,
    etl_version TEXT NOT NULL,
    status TEXT NOT NULL,
    source_fingerprint TEXT NOT NULL,
    packages_loaded INTEGER,
    detail_packages_loaded INTEGER,
    items_loaded INTEGER,
    issues_logged INTEGER,
    checks_failed INTEGER,
    message TEXT,
    PRIMARY KEY (import_id)
);

CREATE TABLE IF NOT EXISTS SOURCE_DOCUMENTS (
    source_document_id TEXT NOT NULL,
    source_document_name TEXT NOT NULL,
    source_file_name TEXT NOT NULL,
    batch_id TEXT NOT NULL,
    category TEXT NOT NULL,
    file_sha256 TEXT NOT NULL,
    file_size_bytes INTEGER NOT NULL,
    sheet_count INTEGER NOT NULL,
    summary_sheet TEXT,
    detail_sheet_count INTEGER,
    summary_title TEXT,
    po_number TEXT,
    summary_invoice_number TEXT,
    shipper TEXT,
    consignee TEXT,
    port_of_loading TEXT,
    port_of_discharge TEXT,
    summary_note TEXT,
    imported_at TIMESTAMP NOT NULL,
    import_version TEXT NOT NULL,
    import_id TEXT NOT NULL,
    PRIMARY KEY (source_document_id),
    FOREIGN KEY (batch_id) REFERENCES REFERENCE_BATCH(batch_id),
    FOREIGN KEY (category) REFERENCES REFERENCE_CATEGORY(category_id),
    FOREIGN KEY (import_id) REFERENCES IMPORT_HISTORY(import_id)
);

CREATE TABLE IF NOT EXISTS SOURCE_SHEETS (
    source_sheet_id TEXT NOT NULL,
    source_document_id TEXT NOT NULL,
    sheet_name TEXT NOT NULL,
    sheet_index INTEGER NOT NULL,
    sheet_state TEXT NOT NULL,
    sheet_role TEXT NOT NULL,
    in_scope INTEGER NOT NULL,
    used_range TEXT,
    max_row INTEGER,
    max_column INTEGER,
    merged_ranges INTEGER,
    formula_cells INTEGER,
    error_value_cells INTEGER,
    header_row INTEGER,
    data_start_row INTEGER,
    data_end_row INTEGER,
    summary_package_rows INTEGER,
    detail_blocks INTEGER,
    material_item_rows INTEGER,
    empty_template_rows INTEGER,
    total_rows INTEGER,
    unlabelled_total_rows INTEGER,
    metadata_rows INTEGER,
    notes TEXT,
    PRIMARY KEY (source_sheet_id),
    FOREIGN KEY (source_document_id) REFERENCES SOURCE_DOCUMENTS(source_document_id)
);

CREATE TABLE IF NOT EXISTS PACKAGE_MASTER (
    package_id TEXT NOT NULL,
    batch_id TEXT NOT NULL,
    category TEXT NOT NULL,
    source_document_id TEXT NOT NULL,
    source_sheet TEXT NOT NULL,
    source_row INTEGER NOT NULL,
    source_sn INTEGER,
    masterlist_item_no TEXT,
    masterlist_sub_item_no TEXT,
    package_number_original TEXT NOT NULL,
    package_number_normalized TEXT NOT NULL,
    package_group TEXT,
    package_batch_code TEXT,
    package_seq INTEGER,
    package_seq_total INTEGER,
    package_number_format TEXT NOT NULL,
    equipment_number TEXT,
    description_en TEXT,
    description_cn TEXT,
    package_quantity DOUBLE PRECISION,
    package_type TEXT,
    package_type_normalized TEXT,
    length_mm DOUBLE PRECISION,
    width_mm DOUBLE PRECISION,
    height_mm DOUBLE PRECISION,
    volume_m3 DOUBLE PRECISION,
    net_weight_kg DOUBLE PRECISION,
    gross_weight_kg DOUBLE PRECISION,
    mdr_number TEXT,
    mdr_status TEXT,
    mdr_status_code TEXT,
    rfs_material_receiving TEXT,
    inspection_date DATE,
    inspection_date_original TEXT,
    received_quantity DOUBLE PRECISION,
    remark TEXT,
    site_annotation TEXT,
    imported_at TIMESTAMP NOT NULL,
    import_version TEXT NOT NULL,
    PRIMARY KEY (package_id),
    UNIQUE (source_document_id, source_sheet, source_row),
    FOREIGN KEY (batch_id) REFERENCES REFERENCE_BATCH(batch_id),
    FOREIGN KEY (category) REFERENCES REFERENCE_CATEGORY(category_id),
    FOREIGN KEY (source_document_id) REFERENCES SOURCE_DOCUMENTS(source_document_id),
    FOREIGN KEY (mdr_status_code) REFERENCES REFERENCE_MDR_STATUS(mdr_status_code)
);

CREATE TABLE IF NOT EXISTS PACKAGE_MDR (
