    mdr_seq INTEGER NOT NULL,
    mdr_number TEXT NOT NULL,
    PRIMARY KEY (package_id, mdr_seq),
    FOREIGN KEY (package_id) REFERENCES PACKAGE_MASTER(package_id)
);

